<script lang="ts">
  import { onMount } from 'svelte';
  import { api, useQuery, type RoomSummary } from '../data';
  import type { CallController } from '../call/controller.svelte';
  import Avatar from './Avatar.svelte';
  import Icon from './Icon.svelte';
  let { call, room, collapse, notice }: { call: CallController; room: RoomSummary; collapse: () => void; notice: (text: string) => void } = $props();
  const participants = useQuery(api.voice.participants, () => ({ room: room._id }));
  let spotlight = $state(''), drawing = $state(false), isDrawing = false, stroke: [number, number][] = [], share = $state<HTMLDivElement>()!;
  const seconds = $derived(Math.max(0, Math.floor((call.clock - call.startedAt) / 1000)));
  function position(e: PointerEvent): [number, number] { const r = share.getBoundingClientRect(); return [Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)), Math.max(0, Math.min(1, (e.clientY - r.top) / r.height))]; }
  function move(e: PointerEvent) { const pos = position(e); call.send({ type: 'pointer', participantId: 'you', shareMid: 'demo-screen', pos }); if (isDrawing) { stroke.push(pos); if (stroke.length > 1) call.send({ type: 'stroke', participantId: 'you', shareMid: 'demo-screen', points: stroke.slice(-2), color: '#a889ed' }); } }
  onMount(() => { const timer = setInterval(() => { if (call.sharing) { call.send({ type: 'pointer', participantId: 'maya', shareMid: 'demo-screen', pos: [.58 + Math.sin(Date.now() / 3000) * .1, .6 + Math.cos(Date.now() / 4000) * .08] }); } }, 500); return () => clearInterval(timer); });
</script>
<div class="stage-view">
  <div class="stage-intro"><div><span class="eyebrow"><span class="live-dot"></span> A LITTLE CLOSER</span><h1>Good company.<span>No agenda needed.</span></h1></div><button class="button" onclick={collapse}><Icon name="collapse" size={15}/>Keep browsing</button></div>
  <div class="stage-toolbar"><span><span class="live-dot"></span>Live in {room.name}<span class="dot-separator">·</span>{Math.floor(seconds / 60)}:{String(seconds % 60).padStart(2, '0')}<span class="dot-separator">·</span>{participants.data?.length ?? 0} people</span><button class="text-button" onclick={() => notice('Pop-out is coming with the desktop app. Your call stays here for now.')}><Icon name="external" size={15}/>Pop out</button></div>
  {#if call.sharing}<div class="screen-share-header"><span><Icon name="share" size={15}/>You’re sharing a preview<span class="muted">· Point to show, draw to explain</span></span><div class="segmented">{#each ['Text', 'Motion'] as mode}<button class:active={call.shareMode === mode} onclick={() => call.setShareMode(mode as 'Text' | 'Motion')}>{mode}</button>{/each}</div><button class:active={drawing} class="icon-button" aria-label="Draw on screen" aria-pressed={drawing} onclick={() => drawing = !drawing}><Icon name="edit" size={16}/></button></div>
  <!-- svelte-ignore a11y_no_noninteractive_tabindex, a11y_no_noninteractive_element_interactions (Interactive drawing surface supports pointer and keyboard input.) -->
  <div class="shared-screen" bind:this={share} class:drawing role="application" aria-label="Shared screen; move to point, enable drawing to annotate" tabindex="0" onpointermove={move} onpointerdown={e => { if (drawing) { isDrawing = true; stroke = [position(e)]; share.setPointerCapture(e.pointerId); } }} onpointerup={() => isDrawing = false} onpointercancel={() => isDrawing = false} onpointerleave={() => { if (!isDrawing) call.send({ type: 'pointer', participantId: 'you', shareMid: 'demo-screen', pos: null }); }} onkeydown={e => { if (e.key === 'Enter') { call.send({ type: 'pointer', participantId: 'you', shareMid: 'demo-screen', pos: [.5, .5] }); } if (e.key === 'd') call.send({ type: 'stroke', participantId: 'you', shareMid: 'demo-screen', points: [[.4, .6], [.5, .5], [.6, .6]], color: '#a889ed' }); }}>
    <div class="screen-browser"><i></i><i></i><i></i><span>fieldwork.design / a-new-chapter</span><Icon name="lock" size={10}/></div><img src="/direction.svg" alt="Fieldwork design preview: A little room to grow" draggable="false"/>
    <svg class="annotations" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-hidden="true">{#each call.strokes as s (s.id)}<polyline points={s.points.map(p => `${p[0] * 1000},${p[1] * 1000}`).join(' ')} fill="none" stroke={s.color} stroke-width="4" stroke-linecap="round" class="annotation-stroke"/>{/each}</svg>
    {#each Object.entries(call.pointers) as [user, pointer]}<span class="share-pointer" style:left={`${pointer.pos.x * 100}%`} style:top={`${pointer.pos.y * 100}%`}><span></span><strong>{user === 'you' ? 'You' : participants.data?.find(p => p.user === user)?.name.split(' ')[0] ?? user}</strong></span>{/each}
  </div>{/if}
  <div class="stage-tiles" class:with-share={call.sharing} class:has-spotlight={!!spotlight}>
    {#each participants.data ?? [] as p (p.user)}<div class="stage-tile" class:spotlight={spotlight === p.user} class:speaking={(call.levels[p.user] ?? 0) > .4 && !p.muted} style:--tile-color={p.color}>
      <button class="tile-main" aria-label={`Spotlight ${p.name}`} onclick={() => spotlight = spotlight === p.user ? '' : p.user}><Avatar name={p.name} color={p.color} size={call.sharing ? 50 : spotlight === p.user ? 100 : 78} speaking={(call.levels[p.user] ?? 0) > .4 && !p.muted}/></button>
      <div class="tile-label"><strong>{p.name}{p.user === 'you' ? ' (you)' : ''}</strong>{#if call.raised.includes(p.user)}<span>✋</span>{/if}{#if p.muted}<Icon name="micOff" size={14}/>{:else}<span class="audio-bars">{#each [0, 1, 2, 3] as i}<i style:height={`${4 + (call.levels[p.user] ?? 0) * (i % 2 ? 16 : 10)}px`}></i>{/each}</span>{/if}</div>
      <label class="tile-volume"><span class="sr-only">Volume for {p.name}</span><Icon name="volume" size={12}/><input type="range" min="0" max="1.5" step=".05" value={call.volumes[p.user]?.volume ?? 1} oninput={e => call.setParticipantVolume(p.user, +e.currentTarget.value)}/></label>
    </div>{/each}
  </div>
  <div class="call-reactions" aria-live="polite">{#each call.reactions as r (r.id)}<span class="floating-reaction" style:left={`${20 + r.id * 19 % 60}%`}>{r.emoji}<small>{r.user === 'you' ? 'You' : r.user}</small></span>{/each}</div>
  <div class="stage-bottom"><div class="quality-label"><Icon name="audio" size={18}/><span>Your audio: <strong>{call.quality}</strong><small>{call.audio.studio ? 'Studio · Every little detail' : 'Clear voices. A little less noise.'}</small></span></div><div class="stage-controls"><button class:control-off={call.muted} aria-label={call.muted ? 'Unmute' : 'Mute'} onclick={() => call.toggleMute()}><Icon name={call.muted ? 'micOff' : 'mic'}/></button><button class:control-off={call.deafened} aria-label="Toggle deafen" onclick={() => call.toggleDeafen()}><Icon name="headphones"/></button><button class:control-on={call.sharing} aria-label={call.sharing ? 'Stop sharing' : 'Share your screen'} onclick={() => call.toggleShare()}><Icon name="share"/></button><button class:control-on={call.raised.includes('you')} aria-label="Raise hand" aria-pressed={call.raised.includes('you')} onclick={() => call.send({ type: 'raiseHand', participantId: 'you', raised: !call.raised.includes('you') })}><Icon name="hand"/></button><button class="leave-control" aria-label="Leave this call" onclick={() => { call.leave(); collapse(); }}><Icon name="leave"/></button></div><div class="stage-emoji">{#each ['💜', '✨', '🙌', '😂'] as em}<button aria-label={`Send ${em} in call`} onclick={() => call.send({ type: 'reaction', participantId: 'you', emoji: em })}>{em}</button>{/each}</div></div>
</div>
